async () => {
  // 1. Get complaint mails
  const mailsResp = await api.get('/mails', { label: 'complaint' });
  const mails = mailsResp.items;
  // 2. Extract unique customer IDs where customer_id not null
  const custIdsSet = new Set();
  for (const m of mails) {
    if (m.customer_id) custIdsSet.add(m.customer_id);
  }
  const custIds = Array.from(custIdsSet);
  // 3. Fetch each customer and collect tiers
  const tiers = [];
  for (const id of custIds) {
    const cust = await api.get(`/customers/${id}`);
    tiers.push({ id, tier: cust.tier });
  }
  // 4. Return unique tiers list
  const uniqueTiers = [...new Set(tiers.map(t => t.tier))];
  console.log('tiers', tiers);
  return { uniqueTiers, count: tiers.length };
}

async () => {
  const mailsResp = await api.get('/mails', { label: 'complaint' });
  const mails = mailsResp.items;
  const custIds = [...new Set(mails.map(m => m.customer_id).filter(id => id))];
  const tiers = [];
  for (const id of custIds) {
    const cust = await api.get(`/customers/${id}`);
    tiers.push(cust.tier);
  }
  const uniqueTiers = [...new Set(tiers)];
  return { uniqueTiers, totalCustomers: custIds.length };
}

